                        }
                        catch (Exception ex)
                        {
                            Logging.SaveLog(ex.Message, ex);
                        }
                        finally
                        {
                            semaphore.Release(); // 释放信号量
                        }
                    }));
                }

                await Task.WhenAll(tasks); // 等待所有任务完成
            }
            catch (Exception ex)
            {
                Logging.SaveLog(ex.Message, ex);
            }
            finally
