Same script on Powershell for Windows users:

```powershell
# Directory with .srs files (change to your directory)
# $TARGET_DIR = "$env:LOCALAPPDATA\v2rayN\bin\srss"
$TARGET_DIR = "~\Apps\v2rayN\bin\srss"

# Base url to download from
$BASE_URL = "https://cdn.jsdelivr.net/gh/runetfreedom/russia-v2ray-rules-dat@release/sing-box/rule-set"

# Check if directory exist
if (-not (Test-Path -Path $TARGET_DIR)) {
    Write-Host "❌ Error: Directory '$TARGET_DIR' not found"
    exit 1
}

# Loop through all .srs files in directory
Get-ChildItem -Path $TARGET_DIR -Filter *.srs | ForEach-Object {
    $filename = $_.Name

    # Check category
    if ($filename -like "geoip-*") {
        $category = "geoip"
    }
    elseif ($filename -like "geosite-*") {
        $category = "geosite"
    }
    else {
        Write-Host "⚠️ Skip Unknown file: $filename"
        return
    }

    # Build download url
    $url = "$BASE_URL-$category/$filename"
    Write-Host "📥 Update $filename from $url"

    try {
        # Download and overwrite file
        Invoke-WebRequest -Uri $url -OutFile $_.FullName -ErrorAction Stop

        # Check if downloaded file not empty
        if ((Get-Item $_.FullName).Length -gt 0) {
            Write-Host "✅ Successfully updated: $filename"
        }
        else {
            Write-Host "❌ Error: Empty file $filename"
        }
    }
    catch {
        Write-Host "❌ Error: Download Failed $filename"
        Write-Host "   Reason: $($_.Exception.Message)"
    }
}
```

