问deepseek：“C# linux 单实例”，看了一下，感觉靠谱，很多方案，比如

1. 使用 Mutex（跨平台推荐）
```C#
using System;
using System.Threading;

class Program
{
    static void Main(string[] args)
    {
        // 使用全局 Mutex，名称需要唯一
        bool createdNew;
        var mutex = new Mutex(true, "Global\\MyUniqueAppName", out createdNew);

        if (!createdNew)
        {
            Console.WriteLine("程序已经在运行！");
            Environment.Exit(0);
        }

        try
        {
            // 保持 Mutex 不被释放
            // 主程序逻辑
            Console.WriteLine("程序启动成功，按任意键退出...");
            Console.ReadKey();
        }
        finally
        {
            mutex.ReleaseMutex();
        }
    }
}
```

6. 使用 .NET Core 的 System.Threading.Mutex（改进版）
```C#
using System;
using System.Threading;
using System.Runtime.InteropServices;

class Program
{
    // 导入Linux的setenv函数
    [DllImport("libc", SetLastError = true)]
    private static extern int setenv(string name, string value, int overwrite);

    static void Main(string[] args)
    {
        // 设置唯一的 Mutex 名称
        string mutexName = "Global\\MyApp_" + 
                          Environment.GetEnvironmentVariable("USER") + "_" +
                          Environment.MachineName.GetHashCode().ToString("X");

        // 或者在 Linux 上使用文件系统路径
        if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
        {
            mutexName = "/tmp/MyApp_" + 
                       Environment.GetEnvironmentVariable("USER") + ".mutex";
        }

        using (var mutex = new Mutex(true, mutexName, out bool createdNew))
        {
            if (!createdNew)
            {
                Console.WriteLine("程序已经在运行！");

                // 可选：激活已有实例
                ActivateExistingInstance();
                Environment.Exit(0);
            }

            try
            {
                // 主程序逻辑
                Console.WriteLine("程序启动成功...");

                // 保持 Mutex
                Console.ReadLine();
            }
            finally
            {
                mutex.ReleaseMutex();
            }
        }
    }

    static void ActivateExistingInstance()
    {
        // 可以通过各种方式激活已有实例：
        // 1. 发送信号
        // 2. 写入管道
        // 3. 使用 D-Bus
        Console.WriteLine("尝试激活已有实例...");
    }
}
```

